int main() {
    // Create detector
    auto detector = std::make_unique&lt;jetbot::detection::YOLOv8Detector&gt;();

    // Initialize with model
    if (!detector-&gt;initialize("/models/yolov8n.engine")) {
        std::cerr &lt;&lt; "Failed to initialize detector" &lt;&lt; std::endl;
        return -1;
    }

    // Load image
    cv::Mat image = cv::imread("test.jpg");

    // Perform detection
    auto detections = detector-&gt;detect(image, 0.5f);

    // Process results
    for (const auto&amp; det : detections) {
        std::cout &lt;&lt; "Detected: " &lt;&lt; det.class_name 
